/**
 * The visual presenter's panel: the picture or diagram for the explanation NEXUS is giving, on the robot's right
 * (beside it on wide screens, above it on narrow ones — never over it). It fades/slides in, crossfades when the visual
 * changes, and fades out when the next reply has none. Images are credited (author, licence, source) and link to their
 * pages; diagrams are labelled as generated by the AI and drawn by the app.
 */
import { useEffect, useRef, useState } from 'react';
import { companion } from '../core/runtime';
import { useSnapshot } from '../components/hooks';
import { Icon } from '../components/Icon';
import { DiagramView } from './DiagramView';
import { attention, rectPoint } from '../character3d/attention';
import type { PresentedVisual } from '../core/companion';

const LEAVE_MS = 320;

function Body({ v }: { v: PresentedVisual }) {
  const r = v.request;
  if (r.kind === 'diagram') return <figure className="vp-figure"><DiagramView diagram={r.diagram} />{r.caption && <figcaption className="vp-caption">{r.caption}</figcaption>}</figure>;
  if (v.status === 'loading') return <div className="vp-loading" role="status"><span className="vp-spinner" aria-hidden />Finding a picture of “{r.query}”…</div>;
  if (v.status === 'failed' || !v.image) return <p className="vp-failed" role="status">{v.error ?? 'No picture available.'}</p>;
  const im = v.image;
  return (
    <figure className="vp-figure">
      <div className="vp-img-wrap"><img className="vp-img" src={im.url} width={im.width} height={im.height} alt={r.caption || im.title} referrerPolicy="no-referrer" decoding="async" /></div>
      <figcaption className="vp-caption">{r.caption || im.title}</figcaption>
      <p className="vp-credit" data-testid="vp-credit">
        <span>{im.author !== 'Unknown' ? im.author : 'Author unknown'}</span> · {im.licenseUrl ? <a href={im.licenseUrl} target="_blank" rel="noopener noreferrer">{im.license}</a> : <span>{im.license}</span>} ·{' '}
        <a href={im.fileUrl} target="_blank" rel="noopener noreferrer">{im.source}</a> · <a href={im.pageUrl} target="_blank" rel="noopener noreferrer">Wikipedia: {im.title}</a>
      </p>
    </figure>
  );
}

export function VisualPanel({ docked = false }: { docked?: boolean }) {
  const snap = useSnapshot();
  const v = snap.visual;
  // keep the last visual on screen while it fades out
  const [shown, setShown] = useState<PresentedVisual | null>(v);
  const [leaving, setLeaving] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null);
  useEffect(() => {
    if (timer.current) { clearTimeout(timer.current); timer.current = null; }
    if (v) { setShown(v); setLeaving(false); return; }
    if (!shown) return;
    setLeaving(true);
    timer.current = setTimeout(() => { setShown(null); setLeaving(false); }, LEAVE_MS);
    return () => { if (timer.current) clearTimeout(timer.current); };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [v]);
  // IVES ↔ the robot: NEXUS knows where the visual really is on the page — it looks there, and presents it
  const panel = useRef<HTMLElement | null>(null);
  useEffect(() => {
    if (!shown || leaving) { attention.set('visual', null); return; }
    attention.set('visual', { label: shown.request.kind, point: () => rectPoint(panel.current?.querySelector('.vp-body') ?? panel.current, 0.4, 0.45) });
    const id = setTimeout(() => attention.focus('visual'), 60);
    return () => clearTimeout(id);
  }, [shown?.id, leaving]); // eslint-disable-line react-hooks/exhaustive-deps
  useEffect(() => () => attention.set('visual', null), []);
  if (!shown) return null;
  const r = shown.request;
  // honest source label: a diagram described by the language model, or one from the scripted demo brain
  const byAI = snap.messages.find((m) => m.id === shown.msgId)?.meta?.isLLM ?? !!snap.caps?.isLLM;
  const kind = r.kind === 'diagram' ? (byAI ? 'Diagram · described by the AI, drawn by NEXUS' : 'Diagram · scripted demo') : 'Photo · Wikimedia Commons';
  const title = r.kind === 'diagram' ? r.diagram.title : shown.image?.title ?? r.query;
  return (
    <aside ref={panel} className={`visual-panel${docked ? ' docked' : ''}${leaving ? ' leaving' : ''}`} aria-label={`Visual: ${title}`} data-testid="visual-panel" data-kind={r.kind} data-status={shown.status}>
      <header className="vp-head">
        <span className="vp-kind">{kind}</span>
        <h2 className="vp-title">{title}</h2>
        <button type="button" className="vp-close" onClick={() => companion.dismissVisual()} aria-label="Close the visual" title="Close"><Icon name="close" size={16} /></button>
      </header>
      <div className="vp-body" key={shown.id}><Body v={shown} /></div>
    </aside>
  );
}
